@Riverpod(keepAlive: true) Future<void> appStartup(Ref ref) async {
  await Firebase.initializeApp();
  OneSignal.initialize(appId);
  OneSignal.Notifications.addClickListener((event) {
    ref.read(notificationHandlerProvider.notifier).navigate(event.notification.additionalData['chat_id']);
  });
}

